FILE: sys/arch/rp2040/rp2040/swapram.c

1	/*
2	 * The compressed RAM tier in front of the flash swap unit.
3	 *
4	 * kern/vm_swap.c writes three segments per swapout -- the data area past
5	 * the clean text, the stack, and the USIZE u area -- and dev/flash.c turns
6	 * each 1 KB of that into a 4 KB read-modify-write of QSPI NOR. This file
7	 * compresses the same three segments with heatshrink into a bss pool and
8	 * keeps them there whenever the pool can hold the worst-case output; when
9	 * it cannot, swapout takes the flash path with nothing changed.
10	 *
11	 * The pool holds compressed bytes only. A process whose image is here holds
12	 * no swapmap blocks, and swapout leaves p_daddr, p_saddr, and p_addr zero
13	 * to say so.
14	 *
15	 * Nothing on the swapout and swapin paths sleeps or allocates. The
16	 * encoder, the decoder, and the segment table are file-scope statics,
17	 * which is safe only because swapout and swapin run to completion without
18	 * a context switch: the flash path sleeps inside swap() on B_DONE, and
19	 * this path has no geteblk, no sleep, and no buffer. The same property
20	 * keeps the kernel stack out of it, which matters because USIZE is 3072
21	 * bytes for the u structure and the kernel stack together. The evacuation
22	 * and the epoch requests run in the swapper and in process context, where
23	 * sleeping in swap_with_buf() is the norm; they use the decoder while no
24	 * swapin can, and the pool is closed to new images for their duration.
25	 */
26	
27	#include <sys/param.h>
28	#include <sys/systm.h>
29	#include <sys/user.h>
30	#include <sys/proc.h>
31	#include <sys/vm.h>
