40	#define SR_DATA         SWAPRAM_DATA
41	#define SR_STACK        SWAPRAM_STACK
42	#define SR_U            SWAPRAM_U
43	#define SR_NSEG         SWAPRAM_NSEG
44	
45	/*
46	 * heatshrink emits a literal as nine bits, so the encoder's worst case is
47	 * the input plus an eighth, and the flush adds at most one byte per stream.
48	 * The u area is reserved at this size, because the clock interrupt keeps
49	 * writing into the current process's u between the counting pass and the
50	 * capture, so its exact length is not knowable in advance. The data and
51	 * stack segments, which are the bulk of an image, are reserved at the
52	 * length a counting encode measures instead.
53	 */
54	#define SR_WORST(n)     ((n) + (n) / 8 + 4)
55	
56	/*
57	 * The pool, in the section kern.ldscript places first in RAM so that it
58	 * abuts the user window; under the LARGE epoch it is the top of a large
59	 * process's stack. NOLOAD there and outside the bss clearing, which is
60	 * fine because every byte is written before it is read.
61	 */
62	u_char                  swapram_pool_mem[SWAPRAM_KB * 1024]
63	#ifdef __ELF__          /* the host test on macOS builds this as Mach-O */
64	                            __attribute__ ((section (".swapram_pool")))
65	#endif
66	                            ;
67	#define sr_pool         swapram_pool_mem
68	static struct swapram_seg sr_seg[NPROC + 1];
69	static struct swapram_pool sr_map;
70	static int              sr_ready;
71	static int              sr_spools;
72	static void             sr_poke (void);
73	
74	/*
75	 * One entry per proc slot, indexed by p - proc, because a swapped-out
76	 * process keeps its slot and struct proc has no room for three more fields.
77	 */
78	#if SWAPRAM_KB * 1024 <= 65535
79	typedef u_short sr_offset_t;
80	#else
81	typedef unsigned int sr_offset_t;
82	#endif
83	
84	static struct sr_ent {
85	    unsigned int    e_rlen[SR_NSEG];    /* the length swapin must produce */
86	    sr_offset_t     e_off;              /* pool offset of the reservation */
87	    sr_offset_t     e_res;              /* bytes reserved, then bytes used */
88	    sr_offset_t     e_clen[SR_NSEG];    /* capacity, then compressed bytes */
89	    u_char          e_live;             /* an image is here */
90	} sr_tab[NPROC];
91	
92	#if SWAPRAM_KB * 1024 <= 65535
93	_Static_assert (sizeof (struct sr_ent) == 24,
94	    "SwapRAM process records must remain compact");
95	#endif
