97	static unsigned int
98	sr_compressed_before (struct sr_ent *e, int stop)
99	{
100	    unsigned int size = 0;
101	    int seg;
102	
103	    for (seg = 0; seg < stop; seg++)
104	        size += e->e_clen[seg];
105	    return size;
106	}
107	
108	static unsigned int
109	sr_compressed_size (struct sr_ent *e)
110	{
111	    return sr_compressed_before (e, SR_NSEG);
112	}
113	
114	#ifdef SWAP_IMAGE_ALIGN
115	static size_t
116	sr_flash_span (struct sr_ent *e)
117	{
118	    size_t blocks = btod (e->e_rlen[SR_DATA]) +
119	        btod (e->e_rlen[SR_STACK]) + btod (e->e_rlen[SR_U]);
120	
121	    return (blocks + SWAP_IMAGE_ALIGN - 1) & ~(SWAP_IMAGE_ALIGN - 1);
122	}
123	#endif
