125	/*
126	 * Admission: swapram_out takes an image only while this is set. An
127	 * evacuation clears it first, so no image enters the pool behind the
128	 * move, and the SMALL/LARGE epoch keeps it clear while the pool must
129	 * stay empty.
130	 */
131	static int              sr_admit = 1;
132	
133	/*
134	 * The evacuation request the sysctl posts and the swapper services:
135	 * SWAPRAM_EVAC_IDLE, then SWAPRAM_EVAC_PENDING while the request waits,
136	 * then the result.
137	 */
138	int                     swapram_evac = SWAPRAM_EVAC_IDLE;
139	
140	/*
141	 * The epoch, the processes admitted under LARGE, and the requests the
142	 * swapper answers: sr_large_want asks for LARGE (an evacuation first),
143	 * sr_small_want asks for SMALL once no large process remains. Every
144	 * completed attempt at LARGE steps sr_large_seq, which is how a process
145	 * asleep on swapram_epoch tells a refusal from a wakeup it did not ask
146	 * for.
147	 */
148	int                     swapram_epoch = SWAPRAM_SMALL;
149	static int              sr_nlarge;
150	static int              sr_large_want, sr_small_want;
151	static unsigned int     sr_large_seq;
152	
153	#ifdef RP2040
154	extern unsigned char swapram_codec_work[SWAPRAM_CODEC_WORK_BYTES];
155	#else
156	unsigned char swapram_codec_work[SWAPRAM_CODEC_WORK_BYTES]
157	    __attribute__ ((aligned (4)));
158	#endif
159	static u_char sr_codec_owner;
160	
161	_Static_assert (sizeof (heatshrink_encoder) <= SWAPRAM_CODEC_WORK_BYTES,
162	    "SwapRAM encoder must fit the shared codec workspace");
163	_Static_assert (sizeof (heatshrink_decoder) <= SWAPRAM_CODEC_WORK_BYTES,
164	    "SwapRAM decoder must fit the shared codec workspace");
