166	void *
167	swapram_codec_acquire (unsigned int owner)
168	{
169	    if (owner == 0 || sr_codec_owner != 0)
170	        panic ("swapram: codec workspace busy");
171	    sr_codec_owner = owner;
172	    return swapram_codec_work;
173	}
174	
175	void
176	swapram_codec_release (unsigned int owner)
177	{
178	    if (owner == 0 || sr_codec_owner != owner)
179	        panic ("swapram: codec workspace owner");
180	    sr_codec_owner = 0;
181	}
