183	/* One line per swapout and swapin names the tier that took the image. */
184	int swapramdebug = 0;		/* off by default; the tier is verified. flip to 1 to trace swaps */
185	
186	static void
187	sr_pool_init_once (void)
188	{
189	    if (sr_ready)
190	        return;
191	    swapram_pool_init (&sr_map, sr_pool, sizeof sr_pool, sr_seg,
192	        NPROC + 1);
193	    sr_ready = 1;
194	}
