196	/*
197	 * Exec argument spools share the byte allocator with compressed images.
198	 * A live spool keeps the SMALL epoch because the LARGE user window overlaps
199	 * every byte of the pool. The exec path moves its spool to flash before it
200	 * asks for LARGE and releases every reservation on its common cleanup path.
201	 */
202	int
203	swapram_spool_alloc (unsigned int size, unsigned int *offp)
204	{
205	    sr_pool_init_once ();
206	    if (! sr_admit || swapram_epoch != SWAPRAM_SMALL ||
207	        swapram_pool_alloc (&sr_map, size, offp) < 0)
208	        return -1;
209	    sr_spools++;
210	    return 0;
211	}
212	
213	void
214	swapram_spool_write (unsigned int off, unsigned int pos, const void *src,
215	    unsigned int len)
216	{
217	    if (off > sizeof sr_pool || pos > sizeof sr_pool - off ||
218	        len > sizeof sr_pool - off - pos)
219	        panic ("swapram: spool write");
220	    bcopy (src, sr_pool + off + pos, len);
221	}
222	
223	void
224	swapram_spool_read (unsigned int off, unsigned int pos, void *dst,
225	    unsigned int len)
226	{
227	    if (off > sizeof sr_pool || pos > sizeof sr_pool - off ||
228	        len > sizeof sr_pool - off - pos)
229	        panic ("swapram: spool read");
230	    bcopy (sr_pool + off + pos, dst, len);
231	}
232	
233	void
234	swapram_spool_free (unsigned int off, unsigned int size)
235	{
236	    if (sr_spools <= 0 || swapram_pool_free (&sr_map, off, size) < 0)
237	        panic ("swapram: spool free");
238	    if (--sr_spools == 0 && sr_large_want)
239	        sr_poke ();
240	}
