242	static struct sr_ent *
243	sr_slot(struct proc *p)
244	{
245	    int i = p - proc;
246	
247	    if (i < 0 || i >= NPROC)
248	        panic ("swapram: proc slot");
249	    return &sr_tab[i];
250	}
