252	/*
253	 * Encode len bytes at src. With dst set, the output goes to dst and the
254	 * call returns the compressed length, or -1 when that would exceed cap:
255	 * once cap bytes are out, the encoder is polled into a one-byte scratch
256	 * and any byte it yields is the overflow. With dst NULL nothing is kept,
257	 * every poll lands in the scratch, and the return value is the length
258	 * the same input would produce: the encoder is deterministic, so a
259	 * counting pass and a writing pass over unchanged bytes agree exactly,
260	 * which swapram_put checks. The loop follows heatshrink's own driver:
261	 * poll until the result stops saying HSER_POLL_MORE, because a poll that
262	 * copies nothing may still have output pending.
263	 */
264	static int
265	sr_encode (caddr_t src, unsigned int len, u_char *dst, unsigned int cap)
266	{
267	    heatshrink_encoder *encoder;
268	    unsigned int in = 0, out = 0, moved = 0;
269	    u_char scratch[64];
270	    u_char *buf;
271	    size_t room, n;
272	    HSE_poll_res pres;
273	    HSE_finish_res fres;
274	    int result = -1;
275	
276	    encoder = swapram_codec_acquire (SWAPRAM_CODEC_ENCODER);
277	    heatshrink_encoder_reset (encoder);
278	    for (;;) {
279	        if (in < len) {
280	            if (heatshrink_encoder_sink (encoder, (uint8_t *) src + in,
281	                len - in, &n) < 0)
282	                goto done;
283	            if (n == 0 && out == moved)
284	                goto done;      /* neither side advanced: no termination */
285	            in += n;
286	        } else {
287	            fres = heatshrink_encoder_finish (encoder);
288	            if (fres < 0)
289	                goto done;
290	            if (fres == HSER_FINISH_DONE)
291	                break;
292	        }
293	        moved = out;
294	        do {
295	            if (dst != NULL && out < cap) {
296	                buf = dst + out;
297	                room = cap - out;
298	            } else {
299	                buf = scratch;
300	                room = dst != NULL ? 1 : sizeof scratch;
301	            }
302	            pres = heatshrink_encoder_poll (encoder, buf, room, &n);
303	            if (pres < 0)
304	                goto done;
305	            if (buf == scratch && dst != NULL && n > 0)
306	                goto done;      /* more than cap bytes: overflow */
307	            out += n;
308	        } while (pres == HSER_POLL_MORE);
309	    }
310	    result = (int) out;
311	done:
312	    swapram_codec_release (SWAPRAM_CODEC_ENCODER);
313	    return result;
314	}
315	
316	/*
317	 * Expand clen bytes at pool offset off, refusing to produce more than
318	 * rlen. With dst set the bytes land there. With dst NULL they go through
319	 * the payload of the busy cache buffer bp a block at a time to the flash
320	 * blocks from blk, the path an evacuation takes. Returns the expanded
321	 * length, which the caller checks against the length swapout recorded.
322	 */
323	static int
324	sr_expand (unsigned int off, unsigned int clen, caddr_t dst,
325	    unsigned int rlen, size_t blk, struct buf *bp)
326	{
327	    heatshrink_decoder *decoder;
328	    unsigned int in = 0, out = 0, moved = 0, fill = 0;
329	    size_t n;
330	    u_char *buf;
331	    size_t room;
332	    HSD_poll_res pres;
333	    HSD_finish_res fres;
334	    int result = -1;
335	
336	#define SR_ROOM() do { \
337	        if (dst != NULL) { \
338	            buf = (u_char *) dst + out; \
339	            room = rlen - out; \
340	        } else { \
341	            buf = (u_char *) bp->b_addr + fill; \
342	            room = DEV_BSIZE - fill; \
343	            if (room > rlen - out) \
344	                room = rlen - out; \
345	        } \
346	    } while (0)
347	#define SR_TOOK(n) do { \
348	        out += (n); \
349	        if (dst == NULL) { \
350	            fill += (n); \
351	            if (fill == DEV_BSIZE || out == rlen) { \
352	                swap_with_buf (bp, blk, (size_t) bp->b_addr, fill, \
353	                    B_WRITE | B_SWAPIMAGE); \
354	                blk += btod (fill); \
355	                fill = 0; \
356	            } \
357	        } \
358	    } while (0)
359	
360	    decoder = swapram_codec_acquire (SWAPRAM_CODEC_DECODER);
361	    heatshrink_decoder_reset (decoder);
362	    while (in < clen && out < rlen) {
363	        if (heatshrink_decoder_sink (decoder, sr_pool + off + in,
364	            clen - in, &n) < 0)
365	            goto done;
366	        if (n == 0 && out == moved)
367	            goto done;          /* neither side advanced: no termination */
368	        in += n;
369	        moved = out;
370	        do {
371	            if (out == rlen)
372	                break;
373	            SR_ROOM ();
374	            pres = heatshrink_decoder_poll (decoder, buf, room, &n);
375	            if (pres < 0)
376	                goto done;
377	            SR_TOOK (n);
378	        } while (pres == HSDR_POLL_MORE);
379	    }
380	    for (moved = out + 1; out < rlen; moved = out) {
381	        if (out == moved)
382	            goto done;          /* finish says more and poll yields none */
383	        fres = heatshrink_decoder_finish (decoder);
384	        if (fres < 0)
385	            goto done;
386	        if (fres == HSDR_FINISH_DONE)
387	            break;
388	        do {
389	            if (out == rlen)
390	                break;
391	            SR_ROOM ();
392	            pres = heatshrink_decoder_poll (decoder, buf, room, &n);
393	            if (pres < 0)
394	                goto done;
395	            SR_TOOK (n);
396	        } while (pres == HSDR_POLL_MORE);
397	    }
398	    result = (int) out;
399	done:
400	#undef SR_ROOM
401	#undef SR_TOOK
402	    swapram_codec_release (SWAPRAM_CODEC_DECODER);
403	    return result;
404	}
405	
406	/*
407	 * Claim pool space for a whole image before any of it is compressed.
408	 * Returns 1 when the tier takes the image, 0 when swapout must use flash.
409	 * The data and stack segments are counted first and reserved at exactly
410	 * the length they will compress to; the u area gets the encoder's worst
411	 * case. Every later put therefore fits by construction and swapout never
412	 * has to unwind a half-written image, while a compressible image is
413	 * admitted whenever its real size fits rather than its raw size.
414	 */
415	int
416	swapram_out (struct proc *p, caddr_t dsrc, size_t dlen, caddr_t ssrc,
417	    size_t slen, size_t ulen)
418	{
419	    struct sr_ent *e = sr_slot (p);
420	    unsigned int off, want;
421	    int dn = 0, sn = 0;
422	
423	    sr_pool_init_once ();
424	    if (e->e_live)
425	        panic ("swapram: image already resident");
426	    /*
427	     * Packed-text restoration holds the shared decoder across rdwri sleeps.
428	     * A swapout scheduled during that interval must use flash instead of
429	     * entering the owner-checked codec workspace.
430	     */
431	    if (! sr_admit || sr_codec_owner == SWAPRAM_CODEC_PACKED_TEXT)
432	        return 0;
433	
434	    if (dlen && (dn = sr_encode (dsrc, dlen, NULL, 0)) < 0)
435	        return 0;
436	    if (slen && (sn = sr_encode (ssrc, slen, NULL, 0)) < 0)
437	        return 0;
438	    want = dn + sn + SR_WORST (ulen);
439	    if (swapram_pool_alloc (&sr_map, want, &off) < 0) {
440	        if (swapramdebug)
441	            printf ("swapram: pid %d flash %u bytes (%u compressed), pool %u free\n",
442	                p->p_pid, (u_int) (dlen + slen + ulen), want,
443	                swapram_pool_avail (&sr_map));
444	        return 0;
445	    }
446	    e->e_off = off;
447	    e->e_res = want;
448	    e->e_rlen[SR_DATA] = dlen;
449	    e->e_rlen[SR_STACK] = slen;
450	    e->e_rlen[SR_U] = ulen;
451	    e->e_clen[SR_DATA] = dn;
452	    e->e_clen[SR_STACK] = sn;
453	    e->e_clen[SR_U] = SR_WORST (ulen);
454	    return 1;
455	}
456	
457	/*
458	 * Compress one segment into the reservation swapram_out made. The data
459	 * and stack segments must produce exactly the length the counting pass
460	 * measured: a shorter or longer result means the bytes changed between
461	 * the passes or the encoder is not deterministic, and either is a bug
462	 * rather than a full pool. The u area may come out shorter than its
463	 * worst-case reservation and never longer.
464	 */
465	void
466	swapram_put (struct proc *p, int seg, caddr_t src, size_t len)
467	{
468	    struct sr_ent *e = sr_slot (p);
469	    unsigned int cap, fill;
470	    int n;
471	
472	    if (len != e->e_rlen[seg])
473	        panic ("swapram: segment length changed");
474	    if (len == 0) {
475	        e->e_clen[seg] = 0;
476	        return;
477	    }
478	    cap = e->e_clen[seg];
479	    fill = sr_compressed_before (e, seg);
480	    n = sr_encode (src, len, sr_pool + e->e_off + fill, cap);
481	    if (n < 0)
482	        panic ("swapram: reservation overflow");
483	    if (seg != SR_U && (unsigned int) n != cap)
484	        panic ("swapram: count mismatch");
485	    e->e_clen[seg] = n;
486	}
487	
488	/*
489	 * Release the unused tail of the reservation, which is the u area's slack
490	 * alone, and mark the image resident.
491	 */
492	void
493	swapram_commit (struct proc *p)
494	{
495	    struct sr_ent *e = sr_slot (p);
496	    unsigned int used = sr_compressed_size (e);
497	
498	    if (swapram_pool_trim (&sr_map, e->e_off, e->e_res, used) < 0)
499	        panic ("swapram: trim");
500	    e->e_res = used;
501	    e->e_live = 1;
502	    if (swapramdebug)
503	        printf ("swapram: pid %d ram %u -> %u bytes, pool %u free\n",
504	            p->p_pid,
505	            (u_int) (e->e_rlen[SR_DATA] + e->e_rlen[SR_STACK] +
506	                e->e_rlen[SR_U]),
507	            used, swapram_pool_avail (&sr_map));
508	}
509	
510	/* True when swapin must read this process back out of the pool. */
511	int
512	swapram_present (struct proc *p)
513	{
514	    return sr_slot (p)->e_live;
515	}
