517	/*
518	 * Copy a prefix of a resident image's u area without removing the image.
519	 * Process sysctl needs fields from the first block while a process remains
520	 * swapped out; p_addr is deliberately zero for a SwapRAM image and therefore
521	 * cannot name raw flash.  Stopping the decoder after the requested prefix
522	 * avoids a permanent u-area staging buffer.
523	 */
524	int
525	swapram_uarea_prefix (struct proc *p, void *dst, unsigned int len)
526	{
527	    struct sr_ent *e = sr_slot (p);
528	    unsigned int off;
529	    int n;
530	
531	    if (! e->e_live || len > e->e_rlen[SR_U])
532	        return -1;
533	    off = e->e_off + e->e_clen[SR_DATA] + e->e_clen[SR_STACK];
534	    n = sr_expand (off, e->e_clen[SR_U], dst, len, 0, NULL);
535	    return n == (int) len ? 0 : -1;
536	}
